behavior['17.04'].mutant=`export function primeiro<T>(xs:T[]):T|undefined{return undefined;} export function buscarPorId<T extends {id:string}>(xs:T[],id:string):T|undefined{return xs.find(x=>x.id===id);}`;
behavior['18.03'].mutant=`export function get<T,K extends keyof T>(obj:T,key:K):T[K] { return undefined as T[K]; }`;
behavior['18.06'].mutant=`export const rotasAnotadas:Record<string,{path:string}>={home:{path:'/'},about:{path:'/about'}}; export const rotas={home:{path:'/'},about:{path:'/about'}} as const satisfies Record<string,{path:string}>; export type RouteNameAnotada=keyof typeof rotasAnotadas; export type RouteName=keyof typeof rotas; export function dispatch(name:RouteName):string{return name;}`;
behavior['18.07'].mutant=`type User={id:string;nome:string}; const porId:Record<string,User>={u1:{id:'u1',nome:'Ana'}}; export function nomeDe(id:string):string {return porId[id]?.nome??'';}`;
behavior['18.10'].mutant=`type User={id:string;nome:string}; type Result={ok:true;valor:number}|{ok:false;erro:string}; export type Evento='ok'|'error'|'retry'; export async function loadUser(id:string):Promise<User|null>{return id==='u1'?{id,nome:'Ana'}:null;} export function handle(input:string):Result{return {ok:false,erro:input};} export type LoadedUser=Awaited<ReturnType<typeof loadUser>>; export type PresentUser=NonNullable<LoadedUser>; export type HandleInput=Parameters<typeof handle>[0]; export type SemErro=Exclude<Evento,'error'>; export type SoErro=Extract<Evento,'error'>;`;
behavior['16.04'].test=`import {test} from 'node:test'; import assert from 'node:assert/strict'; import {userFromResponse} from './perfil.ts';
test('aceita payload válido',async()=>assert.deepEqual(await userFromResponse({json:async()=>({id:1,name:'Ana'})}),{id:1,name:'Ana'}));
test('valida os campos do usuário',async()=>{for(const body of [null,[],{id:'1',name:'A'},{id:1,name:2}]){let error;try{await userFromResponse({json:async()=>body});}catch(caught){error=caught;}assert.ok(error);}});
test('preserva como cause o erro de parse original',async()=>{const cause=new Error('json');let observed;try{await userFromResponse({json:async()=>{throw cause;}});}catch(error){observed=error;}assert.equal(observed?.cause,cause);});`;
behavior['16.10'].test=`import {test} from 'node:test'; import assert from 'node:assert/strict'; import {salvarPedido} from './pedido.ts';
test('sucesso mantém contrato público',async()=>assert.equal(await salvarPedido({id:'p1'}),'Pedido salvo.'));
test('Error vira mensagem e preserva cause',async()=>{const original=new Error('disco');let observed;try{await salvarPedido({id:'p1'},original);}catch(error){observed=error;}assert.equal(observed?.message,'Falhou: disco');assert.equal(observed?.cause,original);});
test('valores não Error usam mensagem segura e preservam cause',async()=>{for(const value of ['falhou',{codigo:503},null]){let observed;try{await salvarPedido({id:'p1'},value);}catch(error){observed=error;}assert.equal(observed?.message,'Falhou: Não foi possível salvar o pedido.');assert.equal(observed?.cause,value);}});`;
const rubrics={
 '16.01':['Definir variantes idle/loading/success(data)/error(message) sem combinações impossíveis (0–4).','Atribuir exemplos válidos e incluir um negativo que combine loading, data e error; evidência de typecheck (0–3).','Explicar como a union substitui flags independentes e criar uma variante request própria (0–3).'],
 '17.01':['Classificar identity/pair/first/getById/selectKey pela relação de tipos, parseStatus como union e APIs concretas por contrato (0–4).','Usar fixtures positivos e negativos para provar inferência e K extends keyof T sem any (0–4).','Transferir classificação para APIs de catálogo com justificativa por assinatura (0–2).'],
 '17.02':['Separar genericidade de entidade T e chave ID; manter constraints somente onde necessárias (0–3).','Mostrar inferência preservada em pair/wrap/repository e `undefined` em ausência (0–4).','Incluir chamada inválida e um repositório independente de pedidos (0–3).'],
 '17.06':['Escolher generic, union, assinatura concreta ou overload pela relação real entre entrada e retorno (0–4).','Fornecer snippets válidos/inválidos com diagnóstico TypeScript6.0.3 (0–3).','Justificar o contrato mínimo para filtros sem uma genericidade sem relação (0–3).'],
 '17.09':['Citar trecho real do JS emitido: enum numérico tem reverse mapping, enum string não; objeto `as const` emite valor e alias desaparece (0–5).','Separar valor runtime e typecheck, e testar `erasableSyntaxOnly` (0–3).','Declarar que executor local não prova `node formas.ts` equivalente e propor uma variante de status (0–2).'],
 '18.01':['Ligar UserId a User["id"], RouteName às chaves de routes, Pedido ao retorno da factory e Status ao array literal (0–4).','Demonstrar dependência viva alterando fonte e compilando fixtures antes/depois (0–4).','Separar valor runtime de alias apagado e transferir a um mapa de status (0–2).'],
 '18.02':['Implementar merge raso sem mutar base, provar referência nova e chaves/tipos inválidos (0–4).','Demonstrar que perfil aninhado é substituído inteiro e Partial<T> é raso (0–4).','Explicar validação necessária para JSON externo e transferir a preferências (0–2).'],
 '18.09':['Comparar JS emitido e identificar import type apagado, import de valor preservado e efeito colateral único em ordem (0–4).','Troca para import não-type deve produzir diagnóstico com `verbatimModuleSyntax`; explicar import lateral (0–3).','Usar um cenário de módulo próprio e delimitar o executor local declarado (0–3).'],
 '19.01':['Prever Flags<User> e provar com igualdade type-level executada (0–4).','Negativos de propriedades/valores e variante homomórfica readonly/opcional (0–3).','Transferir para mapa de permissões e separar tipo de runtime (0–3).'],
 '19.02':['Definir conditional com readonly array/tuple e ramo self para não-arrays (0–3).','Provar string[], tuple, number e união readonly/boolean com igualdade type-level (0–4).','Explicar distributividade e criar variante Promise/valor (0–3).'],
 '19.06':['Aplicar -readonly e -? no lugar correto para normalizar X (0–4).','Provar required/mutable e negativos de ausência; descrever exactOptionalPropertyTypes com undefined explícito (0–4).','Transferir para normalização de settings sem afirmar que `-?` remove valor undefined (0–2).'],
 '19.07':['Mostrar exemplo JSON recursivo finito e rejeitar função/Date quando JsonValue é exigido (0–3).','Distinguir recursão de dados de transformação Date→string e preservar shape de PedidoDto (0–3).','Justificar custo/legibilidade e decisão manter/simplificar/deferir; separar parser runtime (0–4).']
};
const transferDefinitions={
 '16.02':{content:'Uma API recebe `preco: string | number | null`. Defina a saída de `formatarPreco(1299)`, `formatarPreco("1299.50")` e `formatarPreco(null)`; escolha e declare uma política para string numérica decimal. Na borda, compare `0` com `"0"` e mostre por que a guarda escolhida não confunde os tipos.',rubric:['Registra saídas concretas para número, string decimal e null, com a política decimal declarada.','Distingue 0 de "0" com guarda compatível e explica a evidência que diferencia os ramos.']},
 '16.03':{content:'Modele uma união `Entrega` para retirada (`lojaId`), entrega expressa (`endereco`, `janela`) e envio postal (`cep`, `codigoRastreio`). Escreva um `switch` que gere a descrição de cada modalidade e acrescente uma quarta variante `armario` para prever o diagnóstico antes de atualizar o handler. Borda: uma retirada não pode carregar `codigoRastreio`.',rubric:['Cada variante contém somente os campos obrigatórios da modalidade e o handler retorna os três textos previstos.','Mostra a combinação inválida e o diagnóstico de exaustividade causado por armario antes da correção.']},
 '16.04':{content:'Adapte o parser para resposta de perfil `{id: "u-8", name: "Lia", avatar: null}` e para `{id: 8, name: "Lia"}`. Defina o resultado esperado para sucesso e a falha pública para `id` numérico e para payload não-objeto; não use cast como validação. Borda: `avatar` ausente deve seguir uma política explícita diferente ou igual a null.',rubric:['Valida o formato em runtime e preserva somente os campos aceitos no objeto retornado.','Demonstra rejeição de id inválido e payload não-objeto e declara a política de avatar ausente/null.']},
 '16.05':{content:'Crie `isProduct(value: unknown): value is Product` para `{sku: string, stock: number}` e filtre uma lista contendo produto válido, sku numérico, stock negativo e null. Defina quais itens permanecem; na borda, decida se stock zero é válido e faça o predicado refletir essa decisão.',rubric:['Predicado estreita unknown apenas após checar propriedades e tipos exigidos.','Lista filtrada e decisão sobre zero/negativo são explícitas e reproduzíveis.']},
 '16.06':{content:'Derive `Theme` de `THEMES = ["light", "dark", "system"] as const` e aplique a uma função `setTheme`. Inclua chamada aceita `system`, recusa `sepia` e explique o que acontece se a lista for alargada para `string[]`. Borda: diferencie readonly no typecheck de congelamento do array em runtime.',rubric:['Mostra a união exata derivada e chamadas positiva/negativa verificáveis.','Explica a perda de literais ao alargar e não afirma que as const congela o valor em runtime.']},
 '16.07':{content:'Acrescente `kind: "ellipse"; rx: number; ry: number` a uma união de figuras com `area`. Registre o erro de exaustividade no ramo `assertNever` antes da correção e depois calcule a área para rx=3 e ry=2. Borda: rx=0 produz zero; não aceite variante sem ry.',rubric:['Apresenta o diagnóstico antes da atualização e liga a correção ao novo discriminante.','Retorna 6π para rx=3/ry=2, trata rx=0 e mantém ry obrigatório.']},
 '16.08':{content:'Estenda a máquina de upload com estado `cancelled` e ação `cancel` válida durante `uploading`, mas inválida em `success`. Escreva a tabela de transições para uploading 40%, cancel, e para sucesso seguido de cancel. Borda: progresso 100 não deve ser aceito como upload ainda ativo se a regra o reserva ao sucesso.',rubric:['Tabela explicita estado/ação/resultado para o fluxo permitido e os dois casos inválidos.','Tipos e reducer concordam sobre cancelamento e sobre o limite de progresso 100.']},
 '16.09':{content:'Adicione o evento `{tipo: "falhou", codigo: number}` ao `EventoPesquisa`. Registre o ponto do handler que deixa de ser exaustivo e a mensagem para codigo 503 após atualizar o switch. Borda: `limpou` não deve carregar `codigo`.',rubric:['Mostra o erro localizado pelo assertNever antes da nova branch e corrige o handler para falhou.','Preserva a forma sem payload de limpou e produz descrição que inclui 503.']},
 '16.10':{content:'Implemente o tratamento de erro de uma operação `exportarRelatorio` rejeitada com `Error("permissão")` e com o valor `{status: 503}`. Especifique a mensagem pública, mantenha o valor original em `cause` e demonstre que sucesso ainda retorna `"Relatório salvo."`. Borda: um `Error` sem message usa texto seguro sem perder o objeto original.',rubric:['Normaliza Error e valor não-Error em mensagens públicas estáveis e mantém a causa original.','Comprova que sucesso conserva o retorno e define a fallback para mensagem vazia.']},
 '17.03':{content:'Implemente `map` sobre `["a", "b"]` para produzir `[[0,"a"],[1,"b"]]`, usando o índice do callback; filtre a lista por índice par. Mostre que a entrada readonly continua igual após ambas as chamadas. Borda: lista vazia gera dois arrays vazios e nenhum callback.',rubric:['Saídas e índices correspondem aos valores declarados; filter preserva o tipo dos elementos.','Evidencia ausência de mutação, comportamento da entrada vazia e callback não chamado nela.']},
 '17.04':{content:'Projete `primeiro` para `readonly (string | number)[]` sem constraint de id e `buscarPorId` para usuários `{id, nome}`. Calcule a inferência de lista vazia e de `[ {id:"p-2", nome:"Nina"} ]`; mostre chamada inválida com número em buscarPorId. Borda: ambas as consultas podem retornar undefined.',rubric:['Só buscarPorId exige `{id:string}`; primeiro mantém o tipo T sem constraint desnecessária.','Registra corretamente `T | undefined` para coleção vazia e ausência de id.']},
 '17.05':{content:'Use `soma` com a tupla readonly `[4, 7, 9] as const` e com uma variável `readonly number[]` contendo `[2, 3]`; resultados esperados: 20 e 5. Mostre que a função não escreve na entrada. Borda: soma de array vazio é 0.',rubric:['Uma assinatura readonly aceita ambos os formatos e calcula os três resultados exatos.','Demonstra que a função não exige mutação nem promete congelar/copiar a entrada.']},
 '17.06':{content:'Escolha assinaturas para estas três APIs: `lerId` sempre recebe string; `normalizar` aceita string ou number e sempre retorna string; `primeiro` retorna o mesmo tipo dos elementos ou undefined. Para cada uma, compare concreta, union e generic/overload, dando uma chamada válida e uma que deve falhar. Borda: explique por que generic sem dependência entrada/saída não agrega informação em lerId.',rubric:['Seleciona assinatura concreta, union e generic conforme a relação que cada contrato realmente preserva.','Exemplos válidos/inválidos demonstram o contrato e rejeitam genericidade ornamental em lerId.']},
 '17.07':{content:'Crie `defineColumns` com parâmetro const genérico para preservar `[{key:"nome", width:120}, {key:"preco", width:80}]` quando o literal é passado diretamente. Mostre tipo literal e rejeite width string. Borda: um array previamente tipado como `Column[]` já perdeu as chaves literais; explique como recuperar a precisão.',rubric:['Inferência conserva as chaves/widths do argumento direto e a restrição rejeita width não numérico.','Distingue const type parameter de recuperar informação já alargada.']},
 '17.08':{content:'Teste um `Cache<string, number>` com relógio controlado: grave chave "a" em now=100 com TTL 20, consulte em 119 e em 120, e depois chame has. Resultado: 7 antes do limite, undefined no limite e false após remoção. Borda: uma chave sem expiração continua presente.',rubric:['Casos usam relógio injetado e provam validade estrita antes do limite e expiração em `now >= expiresAt`.','Expiração remove a entrada observável e não afeta uma entrada sem TTL.']},
 '18.03':{content:'Aplique `get<T,K extends keyof T>` a `{sku:"A-1", disponivel:true, estoque:0}`: registre os tipos retornados para sku e estoque. Mostre que chave ausente não compila; borda: com `noUncheckedIndexedAccess`, compare essa chave literal conhecida com um índice string desconhecido que pode resultar undefined.',rubric:['Relaciona cada chave literal ao tipo da propriedade e a chave inexistente é recusada.','Descreve corretamente o efeito de noUncheckedIndexedAccess para acesso amplo/indeterminado sem enfraquecer K extends keyof T.']},
 '18.04':{content:'Projete `ProfileSummary` para resposta pública `{id, name, avatarUrl?}` e exclua `passwordHash`, `lastLoginIp` e `email`. Mostre um objeto sem avatar e outro com avatar; borda: uma evolução futura de UserRecord com `mfaSecret` não deve aparecer no resumo. Preserve `ProfileCard` como alias compatível.',rubric:['Tipo nomeado inclui somente os campos públicos intencionais e preserva o alias público existente.','Exemplos aceitos cobrem avatar opcional e rejeitam segredos presentes ou adicionados no futuro.']},
 '18.05':{content:'Crie mapa de handlers para comandos `archive: {id:string}`, `rename: {id:string; title:string}` e `refresh: undefined`. Mostre chamadas válidas correlacionadas e o diagnóstico se `rename` for removido; borda: `archive` com payload de rename deve ser recusado.',rubric:['Cada evento tem handler obrigatório e payload próprio, inclusive refresh sem conteúdo.','A retirada de chave e a troca cruzada de payload produzem evidência de erro de tipo.']},
 '18.07':{content:'Implemente `nomeDe(id)` sobre catálogo `u1 -> "Ana"` sem non-null assertion. Defina a política de ausência: lance RangeError com o id solicitado; demonstre consulta u1 e missing. Borda: id vazio também deve seguir a política documentada.',rubric:['A consulta existente retorna o nome e ausências geram RangeError cuja mensagem identifica o id.','Explica como noUncheckedIndexedAccess expõe o resultado possivelmente ausente sem ocultá-lo por assertion.']},
 '18.08':{content:'Defina formulário de busca com `termo` textual obrigatório e `pagina` numérica mínima 1. Para `{termo:"  livro ", pagina:"2"}`, espere `{termo:"livro", pagina:2}`; campo `pagina` ausente lança RangeError com seu nome, e campo extra é ignorado. Borda: pagina `"0"` é rejeitada.',rubric:['Configuração deriva nomes/valores e a conversão/trim produzem o objeto esperado.','Missing field nomeado, página abaixo do mínimo e política de extra são demonstrados.']},
 '18.10':{content:'Derive os tipos de uma nova API `loadUser(): Promise<User | null>` e eventos `created | failed`; extraia retorno com Awaited/ReturnType, remova null e exclua `failed` para compor os eventos de sucesso. Borda: mostre que `handle("failed")` não pertence ao subconjunto e que o tipo extraído não muda o comportamento runtime.',rubric:['Cada utility transforma o tipo de origem correto e a cadeia de unwrap/null/evento é demonstrada.','Negativos confirmam null e failed fora dos subconjuntos; distingue aliases apagados de validação runtime.']},
 '19.03':{content:'Implemente `Unwrap<T>` e `FnResult<T>` para `buscarPedido(): Promise<{id:"p-9"}>`. Registre FnResult como Promise do objeto e Unwrap como objeto ainda envelopado; compare com Awaited<FnResult<...>>. Borda: entrada number preserva number e não deve ser desembrulhada por Unwrap.',rubric:['Asserções mostram a diferença entre retorno imediato e Awaited sem trocar uma utility pela outra.','Number e objeto literal preservam seus tipos previstos; borda é comprovada por type test.']},
 '19.04':{content:'Para `string | number`, compare `IsString<T>` distributivo e `WholeString<T>` não distributivo; registre `true | false` e `false`. Inclua `never` e explique por que o distributivo retorna never, enquanto a forma em tupla responde a uma pergunta sobre a união inteira. Borda: registre também o resultado para `string` puro.',rubric:['Resultados de string, união e never são corretos para ambas as formas.','Explica a diferença de pergunta e mostra a evidência dos type tests, sem atribuir runtime ao alias.']},
 '19.05':{content:'Implemente `on` para Model `{name:string; age:number}` com eventos `nameChanged` e `ageChanged`. Mostre callback string para o primeiro e number para o segundo; borda: rejeite `ageChanged` com callback de string e evento `emailChanged` inexistente.',rubric:['Template literal infere K e entrega Model[K] correspondente ao evento.','Os dois negativos são recusados e exemplos positivos preservam os tipos específicos.']},
 '19.08':{content:'Para um emitter de estoque com `stockChanged: {sku:string; units:number}` e `itemArchived: {sku:string}`, registre os payloads recebidos e prove que `off` remove só o mesmo callback, repetidamente. Borda: tentar registrar `{units:"4"}` para stockChanged deve falhar no typecheck; listeners do outro evento continuam ativos.',rubric:['Suite verifica payload de cada evento e remoção idempotente do callback correto.','Evento distinto permanece isolado; payload incompatível é rejeitado pelo contrato tipado.']},
 '19.09':{content:'Defina brands UserId e InvoiceId com construtores validados. Aceite `u-42` e `inv-8`, rejeite prefixo errado e string vazia em cada construtor, e mostre que `getUser` recusa InvoiceId. Borda: explique que cast explícito pode contornar a marca e que validação runtime continua necessária.',rubric:['Tipos nominais impedem troca acidental e cada construtor valida formato antes de marcar.','Casos inválidos e bypass por assertion são delimitados sem prometer segurança absoluta em runtime.']}
};
const requiredTransferIds=['16.02','16.03','16.04','16.05','16.06','16.07','16.08','16.09','16.10','17.03','17.04','17.05','17.06','17.07','17.08','18.03','18.04','18.05','18.07','18.08','18.10','19.03','19.04','19.05','19.08','19.09'];
for(const id of requiredTransferIds){const definition=transferDefinitions[id];if(!definition||definition.content.length<180||definition.rubric.length<2||!/(borda|limite)/i.test(definition.content)||/(Aplique os critérios a um caso independente|Mostre uma variação com assinatura e dados concretos|Preserve o contrato de .* prove os casos válidos e inválidos)/i.test(definition.content+definition.rubric.join(' ')))throw new Error(`Transferência sem critérios específicos: ${id}`);}
if(new Set(requiredTransferIds.map(id=>transferDefinitions[id].content)).size!==requiredTransferIds.length)throw new Error('Cenários de transferência devem ser independentes por atividade.');

// Complete the stage 15 publication independently of the stage 16-19 map.
const allIds=catalog.filter(item=>['16.','17.','18.','19.'].some(prefix=>item.id.startsWith(prefix))).map(item=>item.id);
const requestedStage=process.argv[2];
const selectedIds=requestedStage?allIds.filter(id=>id.startsWith(`${requestedStage}.`)):allIds;
const learnerSuites=new Set(['19.08']);
for(const id of selectedIds){
  const activity=typed[id];
  const behaviorInfo=behavior[id];
  const topic=catalog.find(item=>item.id===id);
  const transferDefinition=transferDefinitions[id];
  if(requiredTransferIds.includes(id)&&!transferDefinition)throw new Error(`Transferência específica ausente: ${id}`);
  manifest[id].files=manifest[id].files.filter(file=>file!==`tests/${id}.test.js`);
  if(id==='18.06'){
    const solution='# Referência 18.06\n\n`RouteNameAnotada` é `string`, porque a anotação declara um índice aberto. `RouteName` é a união literal `"home" | "about"`, preservada pelo objeto `as const satisfies Record<string, Rota>`. `dispatch("home")` compila e retorna `/`; `dispatch("missing")` e uma rota com `path: 1` falham no TypeScript. Em runtime, `dispatch` lê o caminho configurado. `satisfies` verifica a forma sem substituir o tipo inferido e não valida objetos externos.\n\n## Transferência\nPara `status: {rascunho:"draft",publicado:"live"}`, compare a anotação `Record<string,string>` com `as const satisfies Record<string,string>`. Registre os tipos de `keyof`, uma chamada permitida, uma chave recusada e qual configuração você manteria em um catálogo de rotas.\n';
    write('course-src/solutions/18.06/README.md',solution);
    assessments[id]={environment:'rubric',version:1,checks:['rubric'],referenceDir:'solutions/18.06',rubric:['Comparar annotation versus `as const satisfies`: `RouteNameAnotada` alarga para string e `RouteName` permanece `"home" | "about"` (0–4).','Registrar evidência type-level positiva para `dispatch("home")`, negativa para `dispatch("missing")` e negativa para `path: 1` com TypeScript 6.0.3 (0–3).','Executar dispatch para verificar `/` e `/about`, transferir o padrão para um catálogo de status e separar tipo inferido de validação runtime (0–3).'],transfer:{id:'18.06-transfer',files:[{path:'transfer.md',content:'# Transferência 18.06\n\nPara o mapa `{ rascunho: "draft", publicado: "live" }`, compare `Record<string,string>` com `as const satisfies Record<string,string>`. Inclua `keyof` previsto, chamada válida e chave inválida, uma evidência de compilação e uma decisão para um catálogo de rotas.'}],rubric:['Previsão correta das chaves alargadas e literais com evidência.','Chamada válida/inválida e decisão de projeto justificadas.']},prompt:'Compare os tipos derivados de rotas anotadas e `as const satisfies`, com evidência estática e runtime, e transfira o padrão a um catálogo independente.'};
    continue;
  }
  const sourceFiles={};
  const addSource=(input)=>{
    if(typeof input==='string')sourceFiles[behaviorInfo?.entry||activity?.entry]=input;
    else if(input)for(const [name,content] of Object.entries(input))sourceFiles[name]=content;
  };
  if(activity?.ref)addSource(activity.ref);
  if(behaviorInfo?.ref)addSource(behaviorInfo.ref);
  if(!Object.keys(sourceFiles).length){
    const rubric=rubrics[id];
    if(!rubric)throw new Error(`Missing substantive assessment definition ${id}`);
    const files=manifest[id].files;
    const artifact=files[0];
    const solution=`# Referência ${id}\n\nPara ${topic.title}, inspecione ${artifact} e registre o comportamento previsto com entradas concretas, evidência da relação entre os dados/tipos e um limite relevante. A decisão deve distinguir saída observada, diagnóstico estático e hipótese; valide também uma borda independente e explique por que ela sustenta a conclusão.${transferDefinition?`\n\n## Transferência\n${transferDefinition.content}`:'\n\n## Transferência\nEscolha uma API ou cenário diferente, informe entrada, saída ou diagnóstico esperado, evidência e o que ainda precisaria de execução real.'}\n`;
    write(`course-src/solutions/${id}/README.md`,solution);
    assessments[id]={environment:'rubric',version:1,checks:['rubric'],referenceDir:`solutions/${id}`,rubric,transfer:{id:`${id}-transfer`,files:[{path:'transfer.md',content:`# Transferência ${id}\n\n${transferDefinition?.content||`Aplique os critérios a ${topic.title} em um caso com entrada e resultado/diagnóstico definidos, cite a evidência e explicite o limite da conclusão.`}`}],rubric:transferDefinition?.rubric||rubric},prompt:`Analise ${topic.title} com evidência localizada em ${files.join(', ')} e resolva um caso independente.`};
    continue;
  }
  const tsconfig=behaviorInfo?.tsconfig||activity?.tsconfig;
  const entry=behaviorInfo?.entry||activity?.entry;
  if(id==='18.04')sourceFiles[entry]='type UserRecord={id:string;name:string;email:string;passwordHash:string;avatarUrl:string;lastLoginIp:string;createdAt:string}; export type ProfileSummary={id:string;name:string;avatarUrl?:string}; export type ProfileCard=ProfileSummary;';
  if(id==='19.03')sourceFiles[entry]=sourceFiles[entry].replace('export async function buscarData','async function buscarData');
  if(id==='19.05')sourceFiles[entry]='type Model={name:string;age:number}; declare function on<K extends string & keyof Model>(event:`${K}Changed`,listener:(value:Model[K])=>void):void;';
  if(id==='19.08')sourceFiles[entry]='export type Events={itemAdded:{sku:string};priceChanged:{sku:string;price:number};itemRemoved:{sku:string}}; export type Listener<P>=(payload:P)=>void; export class Emitter<E extends Record<string,unknown>>{#listeners=new Map<keyof E,Set<Listener<unknown>>>();on<K extends keyof E>(evento:K,listener:Listener<E[K]>):void{let set=this.#listeners.get(evento);if(!set){set=new Set();this.#listeners.set(evento,set);}set.add(listener as Listener<unknown>);}off<K extends keyof E>(evento:K,listener:Listener<E[K]>):void{this.#listeners.get(evento)?.delete(listener as Listener<unknown>);}emit<K extends keyof E>(evento:K,payload:E[K]):void{for(const listener of this.#listeners.get(evento)||[])listener(payload);}}';
  if(tsconfig)sourceFiles['tsconfig.json']=JSON.stringify(tsconfig,null,2);
  if(['16.08','17.08','19.08'].includes(id))sourceFiles['package.json']=JSON.stringify({type:'module'},null,2);
  if(['16.08','17.08','19.08'].includes(id)){
    // Starter npm project: identity plus a lockfile, so the local export validates (package.json requires a lock).
    const name=`devpath-${id.replace('.','-')}`;
    const pkg={name,version:'1.0.0',type:'module'};
    const lock={name,version:'1.0.0',lockfileVersion:3,requires:true,packages:{'':{name,version:'1.0.0'}}};
    for(const file of ['package.json','package-lock.json'])if(!manifest[id].files.includes(file))manifest[id].files.push(file);
    write(`course-src/starters/${id}/package.json`,JSON.stringify(pkg,null,2));
    write(`course-src/starters/${id}/package-lock.json`,JSON.stringify(lock,null,2));
  }
  if(id==='19.08')sourceFiles['emitter.test.ts']=`import {test} from "node:test";\nimport assert from "node:assert/strict";\nimport {Emitter,type Events} from "./emitter.ts";\n\ntest("listener recebe apenas o payload tipado do evento",()=>{const emitter=new Emitter<Events>();const values:Events["priceChanged"][]=[];emitter.on("priceChanged",value=>values.push(value));emitter.emit("priceChanged",{sku:"sku-1",price:4});assert.deepEqual(values,[{sku:"sku-1",price:4}]);});\ntest("off remove o callback e pode ser chamado novamente",()=>{const emitter=new Emitter<Events>();let calls=0;const listener=()=>{calls++;};emitter.on("itemRemoved",listener);emitter.off("itemRemoved",listener);emitter.off("itemRemoved",listener);emitter.emit("itemRemoved",{sku:"sku-2"});assert.equal(calls,0);});\ntest("eventos diferentes mantêm seus listeners isolados",()=>{const emitter=new Emitter<Events>();let added=0;let removed=0;emitter.on("itemAdded",()=>{added++;});emitter.on("itemRemoved",()=>{removed++;});emitter.emit("itemAdded",{sku:"sku-3"});assert.equal(added,1);assert.equal(removed,0);});\n`;
  for(const [name,content] of Object.entries(sourceFiles))write(`course-src/solutions/${id}/${name}`,content);
  if(activity?.solution)write(`course-src/solutions/${id}/README.md`,`# Referência ${id}\n\n${activity.solution}\n\n## Transferência\n${transferDefinition?.content||'Implemente uma variação com entrada concreta, resultado esperado, caso de borda e justificativa do contrato.'}\n`);
  else write(`course-src/solutions/${id}/README.md`,`# Referência ${id}\n\n${topic.title}: preserve a assinatura publicada, valide os campos e condições descritos e prove os resultados com casos de sucesso e borda.\n${transferDefinition?`\n## Transferência\n${transferDefinition.content}\n`:''}`);

  const runtime=Boolean(behaviorInfo&&id!=='19.08');
  const typeSources=id==='19.05'?[protectedTypes[id]]:[activity?.test,protectedTypes[id]].filter(Boolean);
  if(runtime){
    write(`course-src/tests/${id}.test.js`,behaviorInfo.test.replaceAll("../","./"));
  }
  if(id==='19.08'){
    if(!manifest[id].files.includes('emitter.test.ts'))manifest[id].files.push('emitter.test.ts');
  }
  const contractTypeFiles=typeSources.map((content,index)=>({path:`contracts/${id}${index===0?'.types':'.api.types'}.ts`,content}));
  const contractMutationIds=new Set(['16.06','16.09','17.03','17.04','17.05','17.07','18.03','18.04','18.05','18.06','18.07','18.08','18.10','19.03','19.04','19.05','19.08','19.09']);
  const typeContractMutants=activity?.mutant&&contractMutationIds.has(id)?Object.entries(activity.mutant).map(([path,content])=>({id:`${id}-type-contract`,files:[{path,content}]})):[];
  const runtimeMutants=runtime&&behaviorInfo.mutant?[{id:`${id}-behavior`,files:[{path:entry,content:behaviorInfo.mutant}]}]:[];
  const refFiles=Object.entries(sourceFiles).map(([path,content])=>({path,content}));
  const checks=['types'];
  if(runtime||id==='19.08')checks.push('behavior','mutation');else checks.push('mutation');
  const assessment={environment:'node-simulated',version:1,checks,entryPath:entry,referenceDir:`solutions/${id}`,...(tsconfig?{tsconfigPath:'tsconfig.json'}:{}),...(contractTypeFiles.length?{contractTypeFiles}:{}),...(typeContractMutants.length?{typeContractMutants}:{}),...(runtime||id==='19.08'?{typecheckMutants:true}:{}),...(runtime?{testPath:`tests/${id}.test.js`,behaviorTestPath:'__devpath_tests__.js',mutantDirs:runtimeMutants,correctFiles:refFiles}:{}),...(id==='19.08'?{studentSuite:true,studentSuiteKind:'runtime',testPath:'starters/19.08/emitter.test.ts',behaviorTestPath:'emitter.test.ts',testPaths:['emitter.test.ts'],mutantDirs:[{id:'off-does-not-remove',files:[{path:entry,content:`export type Events={itemAdded:{sku:string};priceChanged:{sku:string;price:number};itemRemoved:{sku:string}}; export type Listener<P>=(payload:P)=>void; export class Emitter<E extends Record<string,unknown>>{#listeners=new Map<keyof E,Set<Listener<unknown>>>();on<K extends keyof E>(evento:K,listener:Listener<E[K]>):void{let set=this.#listeners.get(evento);if(!set){set=new Set();this.#listeners.set(evento,set);}set.add(listener as Listener<unknown>);}off<K extends keyof E>(evento:K,listener:Listener<E[K]>):void{}emit<K extends keyof E>(evento:K,payload:E[K]):void{for(const listener of this.#listeners.get(evento)||[])listener(payload);}}`}] }],correctFiles:refFiles}:{}),transfer:{id:`${id}-transfer`,files:[{path:'transfer.md',content:`# Transferência ${id}\n\n${transferDefinition?.content||'Mostre uma variação com assinatura e dados concretos, resultado esperado e uma borda que prove o contrato.'}`}],rubric:transferDefinition?.rubric||(activity?.solution?[`Preserve o contrato de ${topic.title}, prove os casos válidos e inválidos e explique a transferência sem generalizar além da evidência.`]:['Aplique os critérios a um caso independente com entrada, saída/diagnóstico e limite explícitos.'])},prompt:`Implemente ${topic.title}; use os arquivos publicados, prove entradas válidas e inválidas e transfira a solução a um caso independente.`};
  if(typeContractMutants.length&&!runtime)assessment.typeContractMutants=typeContractMutants;
  if(id==='19.08')write('course-src/mutants/19.08/off-does-not-remove/emitter.ts',assessment.mutantDirs[0].files[0].content);
  assessments[id]=assessment;
  if(transferDefinition){const published=assessment.transfer;if(published.files[0].content!==`# Transferência ${id}\n\n${transferDefinition.content}`||JSON.stringify(published.rubric)!==JSON.stringify(transferDefinition.rubric))throw new Error(`A transferência publicada diverge da definição por ID: ${id}`);}
}write('course-src/starters/manifest.json',JSON.stringify(manifest,null,2));
write('course-src/assessments.json',JSON.stringify(assessments,null,2));
write('output/learning-execution/task-8b-stages16-19-owned-paths.json',JSON.stringify(owned.sort(),null,2));
console.log(`Stages 16-19: ${allIds.length} activities, ${Object.keys(typed).filter(id=>allIds.includes(id)).length} typed suites, ${Object.keys(behavior).length} declared behavior definitions.`);
